    valid:x where (x>=0) and (x=floor x) and (x mod 2)=1;
    sum valid*valid
    }

{[x;y]
    lo:min(x;y);
    hi:max(x;y);
    r:lo+til 1+hi-lo;
    r:r where (r>=0)&r<=9;
    r where 0=r mod 2
    }

{[x;y]
    ops:x; vals:y;
    applyOp:{[op;a;b]
        $[op~"+";a+b;
          op~"-";a-b;
          op~"*";a*b;
          op~"//";a div b;
          op~"**";prd b#a;
          '"unknown operator"]
     };
    collapse:{[applyOp;grp;ops;vals]
        i:0;
        while[i<count ops;
            $[grp ops[i];
              [
                nv:applyOp[ops[i];vals[i];vals[i+1]];
                vals:(i#vals),nv,(i+2)_vals;
                ops:(i#ops),(i+1)_ops
              ];
              i+:1
             ]
         ];
        (ops;vals)
     };
    r:collapse[applyOp;{x~"**"};ops;vals];
    ops:r 0; vals:r 1;
    r:collapse[applyOp;{x in ("*";"//")};ops;vals];
    ops:r 0; vals:r 1;
    r:collapse[applyOp;{x in ("+";"-")};ops;vals];
    vals:r 1;
    first vals
 }

{[x]
    / function body
